// Light/dark for the web part. Follows the device until someone taps the toggle.
export function startTheme(root) {
  const media = window.matchMedia('(prefers-color-scheme: dark)');
  const saved = () => localStorage.getItem('sg_theme');
  const btn = root.querySelector('#sg-themeToggle');
  function apply() {
    const theme = saved() || (media.matches ? 'dark' : 'light');
    root.dataset.theme = theme;
    if (btn) {
      const next = theme === 'dark' ? 'light' : 'dark';
      btn.setAttribute('aria-label', `Switch to ${next} mode`);
      btn.title = `Switch to ${next} mode`;
      btn.setAttribute('aria-pressed', String(theme === 'dark'));
    }
  }
  const onMedia = () => { if (!saved()) apply(); };
  const onClick = () => { localStorage.setItem('sg_theme', root.dataset.theme === 'dark' ? 'light' : 'dark'); apply(); };
  media.addEventListener('change', onMedia);
  if (btn) btn.addEventListener('click', onClick);
  apply();
  return { dispose() { media.removeEventListener('change', onMedia); } };
}
